  VALUES ?film { dbr:Day_of_the_Cobra dbr:Time_of_Roses }
  ?film dbp:director ?director .
  OPTIONAL { ?director dbp:birthDate ?b1 . }
  OPTIONAL { ?director dbo:birthDate ?b2 . }
}
